//! 拉斯维加斯桌游引擎（空项目占位）
//!
//! 后续实现 `game-engine-core::EnginePlugin`。
//! 规则文档完善后再实现逻辑，见 `README.md`。

//! 桌游引擎核心框架
//!
//! EnginePlugin trait、引擎注册表、对局状态管理（本次内存存储，P3 换 SQLite）。

use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::sync::{Arc, RwLock};

/// 动作描述（暴露给决策模型选择）。
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Action {
    pub id: String,
    pub description: String,
}

/// 对局状态。
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GameState {
    pub game_id: String,
    pub room_id: String,
    pub group_id: String,
    pub status: GameStatus,
    pub players: Vec<String>,
    /// 引擎私有状态（JSON，引擎自行解析）。
    pub data: serde_json::Value,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum GameStatus {
    Active,
    Finished,
}

/// 引擎错误。
#[derive(Debug, thiserror::Error)]
pub enum EngineError {
    #[error("非法动作: {0}")]
    IllegalAction(String),
    #[error("无权限: {0}")]
    PermissionDenied(String),
    #[error("未找到: {0}")]
    NotFound(String),
    #[error("内部错误: {0}")]
    Internal(String),
}

/// 动作执行结果。
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ActionResult {
    pub state: GameState,
    /// 给玩家/主持人的结果文案。
    pub message: String,
    pub finished: bool,
}

/// 引擎插件 trait：纯逻辑，无状态存储（状态由 GameManager 管理）。
pub trait EnginePlugin: Send + Sync {
    fn game_id(&self) -> &'static str;
    fn rules(&self) -> String;
    /// 开桌：创建初始状态。
    fn new_game(&self, room_id: &str, group_id: &str, players: Vec<String>) -> GameState;
    /// 玩家合法动作。
    fn legal_actions(&self, state: &GameState, player_id: &str) -> Vec<Action>;
    /// 执行动作：无条件重校验合法性 + 权限，返回新状态与结果。
    fn execute_action(
        &self,
        state: &GameState,
        player_id: &str,
        action: &str,
    ) -> Result<ActionResult, EngineError>;
}

/// 引擎注册表。
#[derive(Default)]
pub struct EngineRegistry {
    engines: HashMap<String, Arc<dyn EnginePlugin>>,
}

impl EngineRegistry {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn register<E: EnginePlugin + 'static>(&mut self, engine: E) {
        let id = engine.game_id().to_string();
        self.engines.insert(id, Arc::new(engine));
    }

    pub fn get(&self, game_id: &str) -> Option<&Arc<dyn EnginePlugin>> {
        self.engines.get(game_id)
    }

    pub fn game_ids(&self) -> Vec<String> {
        self.engines.keys().cloned().collect()
    }
}

/// 对局管理器（内存存储，本次）。
pub struct GameManager {
    registry: Arc<EngineRegistry>,
    rooms: RwLock<HashMap<String, GameState>>,
    active_by_group: RwLock<HashMap<String, String>>,
}

impl GameManager {
    pub fn new(registry: EngineRegistry) -> Self {
        Self {
            registry: Arc::new(registry),
            rooms: RwLock::new(HashMap::new()),
            active_by_group: RwLock::new(HashMap::new()),
        }
    }

    pub fn registry(&self) -> &Arc<EngineRegistry> {
        &self.registry
    }

    /// 开桌。
    pub fn start_game(
        &self,
        game_id: &str,
        group_id: &str,
        players: Vec<String>,
    ) -> Result<GameState, EngineError> {
        let engine = self
            .registry
            .get(game_id)
            .ok_or_else(|| EngineError::NotFound(format!("游戏 {game_id}")))?;

        // 群内已有活跃对局：清理残留后覆盖开新局（猜拳一轮即终局，残留视为悬挂）
        if let Some(old_room) = self.active_by_group.write().unwrap().remove(group_id) {
            self.rooms.write().unwrap().remove(&old_room);
        }

        let room_id = shared::new_event_id();
        let state = engine.new_game(&room_id, group_id, players);

        self.rooms
            .write()
            .unwrap()
            .insert(room_id.clone(), state.clone());
        self.active_by_group
            .write()
            .unwrap()
            .insert(group_id.to_string(), room_id);

        Ok(state)
    }

    /// 从快照恢复一个对局（引擎重启后调用）。
    pub fn restore(&self, state: GameState) {
        if state.status == GameStatus::Active {
            self.active_by_group
                .write()
                .unwrap()
                .insert(state.group_id.clone(), state.room_id.clone());
        }
        self.rooms
            .write()
            .unwrap()
            .insert(state.room_id.clone(), state);
    }

    pub fn get_active_game(&self, group_id: &str) -> Option<GameState> {
        let room_id = self.active_by_group.read().unwrap().get(group_id)?.clone();
        self.rooms.read().unwrap().get(&room_id).cloned()
    }

    pub fn get_state(&self, room_id: &str) -> Option<GameState> {
        self.rooms.read().unwrap().get(room_id).cloned()
    }

    pub fn legal_actions(
        &self,
        room_id: &str,
        player_id: &str,
    ) -> Result<Vec<Action>, EngineError> {
        let state = self
            .get_state(room_id)
            .ok_or_else(|| EngineError::NotFound(format!("对局 {room_id}")))?;
        let engine = self
            .registry
            .get(&state.game_id)
            .ok_or_else(|| EngineError::NotFound(format!("游戏 {}", state.game_id)))?;
        Ok(engine.legal_actions(&state, player_id))
    }

    pub fn execute_action(
        &self,
        room_id: &str,
        player_id: &str,
        action: &str,
    ) -> Result<ActionResult, EngineError> {
        let state = self
            .get_state(room_id)
            .ok_or_else(|| EngineError::NotFound(format!("对局 {room_id}")))?;
        let engine = self
            .registry
            .get(&state.game_id)
            .ok_or_else(|| EngineError::NotFound(format!("游戏 {}", state.game_id)))?;

        let result = engine.execute_action(&state, player_id, action)?;

        // 保存新状态；终局则解除群活跃对局登记
        self.rooms
            .write()
            .unwrap()
            .insert(room_id.to_string(), result.state.clone());
        if result.finished {
            self.active_by_group
                .write()
                .unwrap()
                .remove(&state.group_id);
        }
        Ok(result)
    }
}

//! game-engine-mcp：把 EnginePlugin 映射为 MCP 统一原语，以 stdio 暴露给 agent-gateway。
//!
//! 统一原语：get_rules / start_game / get_active_game / get_state / get_legal_actions / execute_action。
//! 所有写入路径由 GameManager → EnginePlugin 无条件重校验（合法性 + 权限）。

use game_engine_core::{EngineRegistry, GameManager, GameState, GameStatus};
use rmcp::{
    ServerHandler, ServiceExt,
    handler::server::{router::tool::ToolRouter, wrapper::Parameters},
    tool, tool_handler, tool_router,
};
use std::sync::Arc;

// —— 工具参数类型（MCP tool 入参）——
#[derive(Debug, serde::Deserialize, rmcp::schemars::JsonSchema)]
struct GameIdRequest {
    game_id: String,
}

#[derive(Debug, serde::Deserialize, rmcp::schemars::JsonSchema)]
struct GroupRequest {
    group_id: String,
}

#[derive(Debug, serde::Deserialize, rmcp::schemars::JsonSchema)]
struct StartGameRequest {
    game_id: String,
    group_id: String,
    players: Vec<String>,
}

#[derive(Debug, serde::Deserialize, rmcp::schemars::JsonSchema)]
struct StateRequest {
    room_id: String,
}

#[derive(Debug, serde::Deserialize, rmcp::schemars::JsonSchema)]
struct LegalActionsRequest {
    room_id: String,
    player_id: String,
}

#[derive(Debug, serde::Deserialize, rmcp::schemars::JsonSchema)]
struct ExecuteActionRequest {
    room_id: String,
    player_id: String,
    action: String,
}

#[derive(Clone)]
struct EngineServer {
    tool_router: ToolRouter<Self>,
    manager: Arc<GameManager>,
    storage: Arc<storage::Storage>,
}

impl EngineServer {
    fn new(manager: Arc<GameManager>, storage: Arc<storage::Storage>) -> Self {
        Self {
            tool_router: Self::tool_router(),
            manager,
            storage,
        }
    }
}

#[tool_router(router = tool_router)]
impl EngineServer {
    #[tool(name = "get_rules", description = "获取指定游戏的规则说明")]
    async fn get_rules(&self, Parameters(p): Parameters<GameIdRequest>) -> String {
        match self.manager.registry().get(&p.game_id) {
            Some(e) => e.rules(),
            None => format!("错误: 未找到游戏 {}", p.game_id),
        }
    }

    #[tool(name = "start_game", description = "开桌（确定性），返回对局状态")]
    async fn start_game(&self, Parameters(p): Parameters<StartGameRequest>) -> String {
        match self.manager.start_game(&p.game_id, &p.group_id, p.players) {
            Ok(state) => {
                let state_json = serde_json::to_string(&state).unwrap_or_default();
                let payload = serde_json::json!({ "game_id": p.game_id, "group_id": p.group_id }).to_string();
                if let Err(e) = self.storage.record_game_transition(
                    &shared::new_event_id(),
                    &state.game_id,
                    &state.room_id,
                    "game_started",
                    None,
                    &payload,
                    &state_json,
                    1,
                ) {
                    tracing::warn!("写 game_events 失败: {e:#}");
                }
                state_json
            }
            Err(e) => format!("错误: {e}"),
        }
    }

    #[tool(name = "get_active_game", description = "查询群内当前活跃对局（无则返回 null）")]
    async fn get_active_game(&self, Parameters(p): Parameters<GroupRequest>) -> String {
        match self.manager.get_active_game(&p.group_id) {
            Some(s) => serde_json::to_string(&s).unwrap_or_default(),
            None => "null".to_string(),
        }
    }

    #[tool(name = "get_state", description = "查询对局状态（无则返回 null）")]
    async fn get_state(&self, Parameters(p): Parameters<StateRequest>) -> String {
        match self.manager.get_state(&p.room_id) {
            Some(s) => serde_json::to_string(&s).unwrap_or_default(),
            None => "null".to_string(),
        }
    }

    #[tool(name = "get_legal_actions", description = "查询玩家当前合法动作列表")]
    async fn get_legal_actions(&self, Parameters(p): Parameters<LegalActionsRequest>) -> String {
        match self.manager.legal_actions(&p.room_id, &p.player_id) {
            Ok(actions) => serde_json::to_string(&actions).unwrap_or_default(),
            Err(e) => format!("错误: {e}"),
        }
    }

    #[tool(name = "execute_action", description = "执行动作（引擎无条件重校验合法性+权限）")]
    async fn execute_action(&self, Parameters(p): Parameters<ExecuteActionRequest>) -> String {
        match self.manager.execute_action(&p.room_id, &p.player_id, &p.action) {
            Ok(result) => {
                let state_json = serde_json::to_string(&result.state).unwrap_or_default();
                let payload = serde_json::json!({ "action": p.action, "message": result.message }).to_string();
                if let Err(e) = self.storage.record_game_transition(
                    &shared::new_event_id(),
                    &result.state.game_id,
                    &result.state.room_id,
                    "action_executed",
                    Some(&p.player_id),
                    &payload,
                    &state_json,
                    2,
                ) {
                    tracing::warn!("写 game_events 失败: {e:#}");
                }
                serde_json::to_string(&result).unwrap_or_default()
            }
            Err(e) => format!("错误: {e}"),
        }
    }
}

#[tool_handler(router = self.tool_router)]
impl ServerHandler for EngineServer {}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    // stdio 被 MCP 协议占用，日志必须写 stderr
    tracing_subscriber::fmt()
        .with_writer(std::io::stderr)
        .init();

    let sqlite_path =
        std::env::var("SQLITE_PATH").unwrap_or_else(|_| "data/tabletop.db".to_string());
    let storage = Arc::new(storage::Storage::open(&sqlite_path)?);

    let mut registry = EngineRegistry::new();
    registry.register(rock_paper_scissors::RpsEngine);
    let manager = Arc::new(GameManager::new(registry));

    // 从 SQLite 恢复活跃对局（引擎重启后内存丢失）
    match storage.load_game_snapshots() {
        Ok(snapshots) => {
            for s in snapshots {
                match serde_json::from_str::<GameState>(&s) {
                    Ok(state) => {
                        let is_active = state.status == GameStatus::Active;
                        manager.restore(state.clone());
                        if is_active {
                            tracing::info!("恢复活跃对局 room={}", state.room_id);
                        }
                    }
                    Err(e) => tracing::warn!("恢复对局快照失败: {e:#}"),
                }
            }
        }
        Err(e) => tracing::warn!("加载对局快照失败: {e:#}"),
    }

    let server = EngineServer::new(manager, storage);
    let serving = server.serve(rmcp::transport::stdio()).await?;
    tracing::info!("game-engine-mcp stdio server 已启动");
    serving.waiting().await?;
    Ok(())
}

//! 猜拳（Rock-Paper-Scissors）引擎：一轮对话。
//!
//! 玩家开桌后出拳，引擎随机出拳判定输赢，返回结果文案。
//! 手势解析由引擎内「模拟决策」完成（本次不接 SystemOne）。

use game_engine_core::{Action, ActionResult, EngineError, EnginePlugin, GameState, GameStatus};
use rand::Rng;
use serde_json::json;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Hand {
    Rock,
    Paper,
    Scissors,
}

impl Hand {
    /// 解析玩家手势（中文 / 英文 / emoji，引擎内模拟决策）。
    fn parse(s: &str) -> Option<Hand> {
        match s.trim().to_lowercase().as_str() {
            "石头" | "rock" | "✊" => Some(Hand::Rock),
            "布" | "paper" | "✋" => Some(Hand::Paper),
            "剪刀" | "scissors" | "✌" | "✌️" => Some(Hand::Scissors),
            _ => None,
        }
    }

    fn beats(self, other: Hand) -> bool {
        matches!(
            (self, other),
            (Hand::Rock, Hand::Scissors)
                | (Hand::Scissors, Hand::Paper)
                | (Hand::Paper, Hand::Rock)
        )
    }

    fn name(self) -> &'static str {
        match self {
            Hand::Rock => "石头",
            Hand::Paper => "布",
            Hand::Scissors => "剪刀",
        }
    }
}

pub struct RpsEngine;

impl EnginePlugin for RpsEngine {
    fn game_id(&self) -> &'static str {
        "rps"
    }

    fn rules(&self) -> String {
        "猜拳：一轮定胜负。玩家出「石头/剪刀/布」，机器人随机出拳判定。".to_string()
    }

    fn new_game(&self, room_id: &str, group_id: &str, players: Vec<String>) -> GameState {
        GameState {
            game_id: self.game_id().to_string(),
            room_id: room_id.to_string(),
            group_id: group_id.to_string(),
            status: GameStatus::Active,
            players,
            data: json!({ "player_hand": null, "bot_hand": null, "result": null }),
        }
    }

    fn legal_actions(&self, state: &GameState, _player_id: &str) -> Vec<Action> {
        if state.status == GameStatus::Finished {
            return vec![];
        }
        vec![
            Action { id: "石头".into(), description: "出石头".into() },
            Action { id: "剪刀".into(), description: "出剪刀".into() },
            Action { id: "布".into(), description: "出布".into() },
        ]
    }

    fn execute_action(
        &self,
        state: &GameState,
        player_id: &str,
        action: &str,
    ) -> Result<ActionResult, EngineError> {
        // —— 无条件重校验：合法性 + 权限 ——
        if state.status == GameStatus::Finished {
            return Err(EngineError::IllegalAction("对局已结束".into()));
        }
        if !state.players.iter().any(|p| p == player_id) {
            return Err(EngineError::PermissionDenied(format!("玩家 {player_id} 不在本局")));
        }
        if state.data.get("player_hand").and_then(|v| v.as_str()).is_some() {
            return Err(EngineError::IllegalAction("本轮已出过拳".into()));
        }

        let player_hand = Hand::parse(action)
            .ok_or_else(|| EngineError::IllegalAction(format!("无法识别手势: {action}")))?;

        // 引擎随机出拳（模拟对手）
        let bot_hand = random_hand();

        let result = if player_hand == bot_hand {
            "平局 🤝"
        } else if player_hand.beats(bot_hand) {
            "你赢了！🎉"
        } else {
            "你输了！"
        };

        let message = format!(
            "你出【{}】，我出【{}】——{}",
            player_hand.name(),
            bot_hand.name(),
            result
        );

        let new_state = GameState {
            game_id: state.game_id.clone(),
            room_id: state.room_id.clone(),
            group_id: state.group_id.clone(),
            status: GameStatus::Finished,
            players: state.players.clone(),
            data: json!({
                "player_hand": player_hand.name(),
                "bot_hand": bot_hand.name(),
                "result": result,
            }),
        };

        Ok(ActionResult {
            state: new_state,
            message,
            finished: true,
        })
    }
}

fn random_hand() -> Hand {
    let mut rng = rand::thread_rng();
    match rng.gen_range(0..3) {
        0 => Hand::Rock,
        1 => Hand::Paper,
        _ => Hand::Scissors,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use game_engine_core::{EngineError, GameState, GameStatus};
    use serde_json::json;

    fn new_state() -> GameState {
        GameState {
            game_id: "rps".into(),
            room_id: "room-1".into(),
            group_id: "group-1".into(),
            status: GameStatus::Active,
            players: vec!["p1".into()],
            data: json!({ "player_hand": null, "bot_hand": null, "result": null }),
        }
    }

    #[test]
    fn hand_parse_variants() {
        assert_eq!(Hand::parse("石头"), Some(Hand::Rock));
        assert_eq!(Hand::parse("rock"), Some(Hand::Rock));
        assert_eq!(Hand::parse("✊"), Some(Hand::Rock));
        assert_eq!(Hand::parse("剪刀"), Some(Hand::Scissors));
        assert_eq!(Hand::parse("scissors"), Some(Hand::Scissors));
        assert_eq!(Hand::parse("布"), Some(Hand::Paper));
        assert_eq!(Hand::parse("paper"), Some(Hand::Paper));
        assert_eq!(Hand::parse("✋"), Some(Hand::Paper));
        assert_eq!(Hand::parse("无效"), None);
        assert_eq!(Hand::parse(""), None);
    }

    #[test]
    fn hand_beats_relation() {
        assert!(Hand::Rock.beats(Hand::Scissors));
        assert!(Hand::Scissors.beats(Hand::Paper));
        assert!(Hand::Paper.beats(Hand::Rock));
        assert!(!Hand::Rock.beats(Hand::Paper));
        assert!(!Hand::Paper.beats(Hand::Scissors));
        assert!(!Hand::Scissors.beats(Hand::Rock));
    }

    #[test]
    fn invalid_hand_rejected() {
        let engine = RpsEngine;
        let state = new_state();
        let err = engine.execute_action(&state, "p1", "无效手势").unwrap_err();
        assert!(matches!(err, EngineError::IllegalAction(_)));
    }

    #[test]
    fn non_player_rejected() {
        let engine = RpsEngine;
        let state = new_state();
        let err = engine.execute_action(&state, "p2", "石头").unwrap_err();
        assert!(matches!(err, EngineError::PermissionDenied(_)));
    }

    #[test]
    fn finished_game_rejected() {
        let engine = RpsEngine;
        let mut state = new_state();
        state.status = GameStatus::Finished;
        let err = engine.execute_action(&state, "p1", "石头").unwrap_err();
        assert!(matches!(err, EngineError::IllegalAction(_)));
    }

    #[test]
    fn execute_returns_finished_with_message() {
        let engine = RpsEngine;
        let state = new_state();
        let result = engine.execute_action(&state, "p1", "石头").unwrap();
        assert!(result.finished);
        assert!(result.message.contains("你出【石头】"));
        assert_eq!(result.state.status, GameStatus::Finished);
        assert!(result.state.data["player_hand"].is_string());
        assert!(result.state.data["bot_hand"].is_string());
    }

    #[test]
    fn legal_actions_are_three_hands() {
        let engine = RpsEngine;
        let state = new_state();
        let actions = engine.legal_actions(&state, "p1");
        assert_eq!(actions.len(), 3);
    }
}

